<script setup lang="ts">
import {computed,ref} from 'vue';import {useWorkbench} from '../stores/workbench';import {STATUS_LABELS} from '../features';import StatusBadge from '../components/StatusBadge.vue';import UiIcon from '../components/UiIcon.vue';const s=useWorkbench();const filter=ref('all');const groups=computed(()=>{const m:Record<string,any[]>={};for(const f of s.features){if(filter.value!=='all'&&f.status!==filter.value)continue;(m[f.module]??=[]).push(f)}return m});const counts=computed(()=>Object.keys(STATUS_LABELS).map(k=>({key:k,label:STATUS_LABELS[k],count:s.features.filter(f=>f.status===k).length})));
</script><template><div class="page-heading"><div><div class="eyebrow">能力总览 / M1—M10</div><h1>功能清单</h1><p>动态建模、运行评估与跨课题协同。</p></div><span class="page-icon"><UiIcon name="file" :size="30"/></span></div><div class="stat-grid"><button v-for="c in counts" :key="c.key" class="stat-card clickable" :class="{selected:filter===c.key}" @click="filter=filter===c.key?'all':c.key"><span>{{c.label}}</span><strong>{{c.count}}<small>项</small></strong></button></div><div class="toolbar"><h2>模块与功能</h2><el-select v-model="filter" class="compact-select"><el-option label="全部状态" value="all"/><el-option v-for="(label,key) in STATUS_LABELS" :key="key" :value="key" :label="label"/></el-select></div><section v-for="(items,module) in groups" :key="module" class="panel module-panel"><div class="section-heading"><span class="module-key">{{module}}</span><span class="muted">{{items.length}} 项功能</span></div><div class="feature-grid"><div v-for="f in items" :key="f.id" class="feature-row"><div><strong>{{f.name}}</strong><p>{{f.description}}</p></div><StatusBadge :feature="f.id"/></div></div></section><el-empty v-if="!s.features.length&&!s.loading" description="功能登记表尚未加载，请检查本地服务。"/></template>